    val sys = PartitionDriftSystem()
    println("Velle MockHarness — PartitionDrift")
    println("Commits: commit(NewCreateNote(...)), commit(NewLockNote(...)), commit(NewUnlockNote(...)), commit(NewRenameText(...)), commit(NewBareEdit(...)), commit(NewSafeEdit(...)), commit(NewTransientEdit(...))")
    println("Edit this main to drive the system; state prints below.")

    // <your scenario here>

    println("Tick: " + sys.ticks().size)
    println("Note: " + sys.notes().size)
    println("LockNote: " + sys.lockNotes().size)
    println("UnlockNote: " + sys.unlockNotes().size)
    println("RenameText: " + sys.renameTexts().size)
    println("BareEdit: " + sys.bareEdits().size)
    println("BareEditRefusal: " + sys.bareEditRefusals().size)
    println("SafeEdit: " + sys.safeEdits().size)
    println("EditApplication: " + sys.editApplications().size)
    println("EditRefusal: " + sys.editRefusals().size)
    println("TransientEditRefusal: " + sys.transientEditRefusals().size)
}
